<?php
/**
 * Classifies a stored copy against the running plugin version.
 *
 * @package AgentReady
 */

declare(strict_types=1);

namespace AgentReady\Cache;

defined( 'ABSPATH' ) || exit;

/** Decides whether a stored copy can be served as is, needs a refresh, or must be rebuilt. */
final class Freshness {

	/** Current: serve as is. */
	public const FRESH = 'fresh';
	/** Out of date but from this plugin version: serve it and refresh in the background. */
	public const STALE = 'stale';
	/** No copy is stored. */
	public const MISSING = 'missing';
	/** Generated by another plugin version: rebuild before serving. */
	public const OUTDATED = 'outdated';

	/**
	 * Works out the freshness of a stored copy.
	 *
	 * @param Entry|null $entry   The stored copy, or null when none exists.
	 * @param string     $version Current plugin version.
	 * @return string One of the Freshness constants.
	 */
	public static function classify( ?Entry $entry, string $version ): string {
		if ( null === $entry ) {
			return self::MISSING;
		}

		if ( $entry->generator_version !== $version ) {
			return self::OUTDATED;
		}

		return Entry::STALE === $entry->state ? self::STALE : self::FRESH;
	}
}
